import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { MapPin } from "lucide-react";

import {
  Screen,
  PrimaryButton,
} from "../components/common/UI";

import "../styles/ProductDetails.css";

export default function ProductDetails() {
  const { id } = useParams();
  const navigate = useNavigate();

  const [quantity, setQuantity] = useState(1);
  const [product, setProduct] = useState(null);
  const [merchant, setMerchant] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // TODO: Replace with actual API call to GET /products/:productId
    setProduct({
      _id: id,
      merchant_id: "1",
      name: "Fresh Milk (500ml)",
      unit_label: "500ml bottle",
      description: "Fresh, locally sourced whole milk in a convenient 500ml bottle. Perfect for your daily needs.",
      category: "Dairy",
      product_image: "https://images.unsplash.com/photo-1563636619-e9143da7973b?w=700",
      price: { kes: "57.00", aud: "0.63" },
      in_stock: true
    });
    setMerchant({
      _id: "1",
      business_name: "SupaMart Grocers",
      address: "Moi Avenue, Nairobi"
    });
    setLoading(false);
  }, [id]);

  if (loading) {
    return <Screen title="Product Details" back>Loading...</Screen>;
  }

  if (!product) {
    return (
      <Screen title="Product Details" back>
        <p>Product not found.</p>
      </Screen>
    );
  }

  const isOutOfStock = !product.in_stock;
  const totalPrice = (parseFloat(product.price.kes) * quantity).toFixed(2);
  const totalAud = (parseFloat(product.price.aud) * quantity).toFixed(2);

  const handleAddToBasket = () => {
    // TODO: Implement basket API call
    // POST /baskets or POST /baskets/:basketId/items
    navigate("/basket");
  };

  return (
    <Screen title="Product Details" back>
      <img
        className="detail-photo"
        src={product.product_image}
        alt={product.name}
      />

      <div className="product-detail-header">
        <h2>{product.name}</h2>
        <div className="price-display">
          <b className="orange">KSh {product.price.kes}</b>
          {product.price.aud && (
            <span className="aud-price">≈ AUD {product.price.aud}</span>
          )}
        </div>
      </div>

      <p className="muted small">
        {product.unit_label} · {isOutOfStock ? "Out of stock" : "In stock"}
      </p>

      {merchant && (
        <div className="panel">
          <h3 className="card-title">Merchant</h3>
          <p className="muted small row">
            <MapPin size={13} />
            {merchant.business_name} · {merchant.address}
          </p>
        </div>
      )}

      <div className="panel">
        <h3 className="card-title">Description</h3>
        <p className="muted small">
          {product.description}
        </p>
      </div>

      <div className="row between product-quantity">
        <strong>Quantity</strong>

        <div className="row">
          <button
            onClick={() =>
              setQuantity((previous) =>
                Math.max(1, previous - 1)
              )
            }
            disabled={isOutOfStock}
          >
            −
          </button>

          <b>{quantity}</b>

          <button
            onClick={() =>
              setQuantity((previous) =>
                Math.min(99, previous + 1)
              )
            }
            disabled={isOutOfStock}
          >
            +
          </button>
        </div>
      </div>

      <PrimaryButton 
        onClick={handleAddToBasket}
        disabled={isOutOfStock}
      >
        {isOutOfStock ? "Out of Stock" : `Add to Basket · KSh ${totalPrice}`}
      </PrimaryButton>
    </Screen>
  );
}
